import React, { useState } from 'react';
import { useOutletContext, useParams } from 'react-router-dom';
import './acquire.css';

const InvestorProfile = () => {
  const [activeTab, setActiveTab] = useState('profile');
  
  // Get data from the Outlet context
  const { investors } = useOutletContext();
  const { id } = useParams();
  
  // Find the investor by ID
  const investor = investors.find(i => i.id === parseInt(id)) || investors[0];

  return (
    <div className="investor-profile-page">
      <section className="investor-header py-12 bg-brand-light">
        <div className="container mx-auto px-4">
          <div className="breadcrumb text-gray-600 mb-4">
            <a href="/acquire/investors" className="text-brand-primary hover:underline">Investor Directory</a> / {investor.name}
          </div>
          <div className="flex flex-col md:flex-row items-start md:items-center">
            <div className="investor-avatar bg-brand-primary w-24 h-24 rounded-full flex items-center justify-center text-white text-4xl font-bold mb-6 md:mb-0 md:mr-8">
              {investor.name.charAt(0)}
            </div>
            <div className="investor-info flex-grow">
              <h1 className="text-4xl font-bold mb-2">{investor.name}</h1>
              <p className="text-xl text-gray-700 mb-4">{investor.title}</p>
              <div className="investor-details grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                <div className="detail-item">
                  <span className="font-semibold">Focus:</span> {investor.focus}
                </div>
                <div className="detail-item">
                  <span className="font-semibold">Location:</span> {investor.location}
                </div>
                <div className="detail-item">
                  <span className="font-semibold">Investment Range:</span> {investor.minInvestment} - {investor.maxInvestment}
                </div>
              </div>
              <button className="btn btn-primary">Contact Investor</button>
            </div>
          </div>
        </div>
      </section>

      <section className="investor-content py-12">
        <div className="container mx-auto px-4">
          <div className="tabs mb-8">
            <div className="flex border-b border-gray-200">
              <button
                className={`py-3 px-6 font-medium ${activeTab === 'profile' ? 'text-brand-primary border-b-2 border-brand-primary' : 'text-gray-600 hover:text-gray-900'}`}
                onClick={() => setActiveTab('profile')}
              >
                Profile
              </button>
              <button
                className={`py-3 px-6 font-medium ${activeTab === 'preferences' ? 'text-brand-primary border-b-2 border-brand-primary' : 'text-gray-600 hover:text-gray-900'}`}
                onClick={() => setActiveTab('preferences')}
              >
                Investment Preferences
              </button>
              <button
                className={`py-3 px-6 font-medium ${activeTab === 'portfolio' ? 'text-brand-primary border-b-2 border-brand-primary' : 'text-gray-600 hover:text-gray-900'}`}
                onClick={() => setActiveTab('portfolio')}
              >
                Portfolio
              </button>
            </div>
          </div>

          <div className="tab-content">
            {activeTab === 'profile' && (
              <div className="profile-tab">
                <h2 className="text-2xl font-bold mb-6">About {investor.name}</h2>
                <div className="bg-white rounded-xl shadow-md p-6 mb-8">
                  <h3 className="text-xl font-bold mb-4">Investment Philosophy</h3>
                  <p className="text-gray-700 mb-4">
                    {investor.philosophy}
                  </p>
                  <p className="text-gray-700">
                    With over {investor.experience} years of experience in the industry, we focus on identifying 
                    high-growth opportunities with strong fundamentals and exceptional management teams.
                  </p>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                  <div className="text-center p-4 bg-brand-light rounded-lg">
                    <div className="text-3xl font-bold text-brand-primary">${investor.aum}</div>
                    <div className="text-gray-700">Assets Under Management</div>
                  </div>
                  <div className="text-center p-4 bg-brand-light rounded-lg">
                    <div className="text-3xl font-bold text-brand-primary">{investor.exits}</div>
                    <div className="text-gray-700">Successful Exits</div>
                  </div>
                  <div className="text-center p-4 bg-brand-light rounded-lg">
                    <div className="text-3xl font-bold text-brand-primary">{investor.roi}</div>
                    <div className="text-gray-700">Average ROI</div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'preferences' && (
              <div className="preferences-tab">
                <h2 className="text-2xl font-bold mb-6">Investment Preferences</h2>
                <div className="bg-white rounded-xl shadow-md p-6 mb-8">
                  <h3 className="text-xl font-bold mb-4">Ideal Business Profile</h3>
                  <ul className="list-disc pl-6 space-y-3">
                    {investor.preferences.map((preference, index) => (
                      <li key={index} className="text-gray-700">{preference}</li>
                    ))}
                  </ul>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="bg-white rounded-xl shadow-md p-6">
                    <h3 className="text-xl font-bold mb-4">Financial Requirements</h3>
                    <div className="space-y-4">
                      <div>
                        <h4 className="font-semibold mb-1">Revenue</h4>
                        <p className="text-gray-700">$2M - $20M annually</p>
                      </div>
                      <div>
                        <h4 className="font-semibold mb-1">Growth Rate</h4>
                        <p className="text-gray-700">Minimum 30% year-over-year</p>
                      </div>
                      <div>
                        <h4 className="font-semibold mb-1">Profitability</h4>
                        <p className="text-gray-700">Path to profitability within 18 months</p>
                      </div>
                    </div>
                  </div>
                  
                  <div className="bg-white rounded-xl shadow-md p-6">
                    <h3 className="text-xl font-bold mb-4">Operational Requirements</h3>
                    <div className="space-y-4">
                      <div>
                        <h4 className="font-semibold mb-1">Management Team</h4>
                        <p className="text-gray-700">Experienced leadership with relevant industry expertise</p>
                      </div>
                      <div>
                        <h4 className="font-semibold mb-1">Market Position</h4>
                        <p className="text-gray-700">Defensible market position with competitive advantages</p>
                      </div>
                      <div>
                        <h4 className="font-semibold mb-1">Due Diligence</h4>
                        <p className="text-gray-700">Clean financials and legal documentation</p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </section>

      <section className="cta-section py-16 bg-brand-dark">
        <div className="container mx-auto px-4 text-center">
          <h2 className="text-3xl font-bold mb-4">Connect with {investor.name}</h2>
          <p className="text-xl mb-8 max-w-2xl mx-auto">
            Reach out to discuss potential investment opportunities
          </p>
          <button className="btn btn-primary btn-lg">Contact Investor</button>
        </div>
      </section>
    </div>
  );
};

export default InvestorProfile;