import { useState, useEffect } from 'react';
import { sampleBusinesses, sampleInvestors } from './data';

// Custom hook for acquire functionality
const useAcquire = () => {
  const [businesses, setBusinesses] = useState([]);
  const [investors, setInvestors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Simulate fetching data
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        // Simulate API call delay
        await new Promise(resolve => setTimeout(resolve, 1000));
        
        // In a real app, this would be an API call
        setBusinesses(sampleBusinesses);
        setInvestors(sampleInvestors);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Filter businesses by search term
  const searchBusinesses = (searchTerm) => {
    if (!searchTerm) return businesses;
    
    return businesses.filter(business => 
      business.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      business.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      business.industry.toLowerCase().includes(searchTerm.toLowerCase())
    );
  };

  // Filter investors by search term
  const searchInvestors = (searchTerm) => {
    if (!searchTerm) return investors;
    
    return investors.filter(investor => 
      investor.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      investor.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      investor.focus.toLowerCase().includes(searchTerm.toLowerCase())
    );
  };

  // Get business by ID
  const getBusinessById = (id) => {
    return businesses.find(business => business.id === parseInt(id));
  };

  // Get investor by ID
  const getInvestorById = (id) => {
    return investors.find(investor => investor.id === parseInt(id));
  };

  // Submit a business for sale
  const submitBusiness = async (businessData) => {
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      // In a real app, this would send data to an API
      console.log('Business submitted:', businessData);
      return { success: true, message: 'Business listing submitted successfully!' };
    } catch (err) {
      console.error('Error submitting business:', err);
      return { success: false, message: 'Failed to submit business listing.' };
    }
  };

  return {
    businesses,
    investors,
    loading,
    error,
    searchBusinesses,
    searchInvestors,
    getBusinessById,
    getInvestorById,
    submitBusiness
  };
};

export default useAcquire;