import React from 'react';

const Avatar = ({ 
  src,
  alt,
  name,
  size = 'md',
  shape = 'circle',
  className = '',
  ...props 
}) => {
  // Size classes
  const sizeClasses = {
    xs: 'w-6 h-6',
    sm: 'w-8 h-8',
    md: 'w-10 h-10',
    lg: 'w-12 h-12',
    xl: 'w-16 h-16'
  };

  // Shape classes
  const shapeClasses = {
    circle: 'rounded-full',
    square: 'rounded-md'
  };

  // Get initials from name
  const getInitials = (name) => {
    if (!name) return '';
    
    const names = name.split(' ');
    let initials = names[0].substring(0, 1).toUpperCase();
    
    if (names.length > 1) {
      initials += names[names.length - 1].substring(0, 1).toUpperCase();
    }
    
    return initials;
  };

  // Generate background color based on name
  const generateColor = (name) => {
    if (!name) return 'bg-gray-200';
    
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
      hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    
    const colors = [
      'bg-red-200',
      'bg-orange-200',
      'bg-amber-200',
      'bg-yellow-200',
      'bg-lime-200',
      'bg-green-200',
      'bg-emerald-200',
      'bg-teal-200',
      'bg-cyan-200',
      'bg-sky-200',
      'bg-blue-200',
      'bg-indigo-200',
      'bg-violet-200',
      'bg-purple-200',
      'bg-fuchsia-200',
      'bg-pink-200',
      'bg-rose-200'
    ];
    
    return colors[Math.abs(hash) % colors.length];
  };

  const initials = getInitials(name);
  const bgColor = generateColor(name);

  if (src) {
    return (
      <img
        src={src}
        alt={alt || name}
        className={`${sizeClasses[size]} ${shapeClasses[shape]} object-cover ${
          className
        }`}
        {...props}
      />
    );
  }

  return (
    <div
      className={`${sizeClasses[size]} ${shapeClasses[shape]} ${bgColor} flex items-center justify-center text-gray-800 font-medium ${
        className
      }`}
      {...props}
    >
      {initials}
    </div>
  );
};

export default Avatar;