import React from 'react';

const Button = ({ 
  children,
  type = 'button',
  variant = 'primary',
  size = 'md',
  disabled = false,
  onClick,
  className = '',
  ...props 
}) => {
  // Variant classes
  const variantClasses = {
    primary: 'bg-brand-primary hover:bg-brand-primary-dark text-white focus:ring-brand-primary',
    secondary: 'bg-brand-secondary hover:bg-brand-secondary-dark text-white focus:ring-brand-secondary',
    accent: 'bg-brand-accent hover:bg-brand-accent-dark text-white focus:ring-brand-accent',
    outline: 'bg-transparent border border-brand-primary text-brand-primary hover:bg-brand-primary hover:text-white focus:ring-brand-primary',
    ghost: 'bg-transparent text-brand-primary hover:bg-brand-primary/10 focus:ring-brand-primary',
    danger: 'bg-red-600 hover:bg-red-700 text-white focus:ring-red-500'
  };

  // Size classes
  const sizeClasses = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-4 py-2 text-sm',
    lg: 'px-6 py-3 text-base',
    xl: 'px-8 py-4 text-lg'
  };

  // Disabled classes
  const disabledClasses = disabled 
    ? 'opacity-50 cursor-not-allowed' 
    : 'focus:outline-none focus:ring-2 focus:ring-offset-2';

  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      className={`inline-flex items-center border border-transparent font-medium rounded-md shadow-sm transition-colors duration-200 ${
        variantClasses[variant]
      } ${
        sizeClasses[size]
      } ${
        disabledClasses
      } ${
        className
      }`}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;