import React, { useState } from 'react';
import { useOutletContext, useParams } from 'react-router-dom';
import './acquire.css';

const BusinessDetailPage = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [showContactForm, setShowContactForm] = useState(false);
  
  // Get data from the Outlet context
  const { businesses } = useOutletContext();
  const { id } = useParams();
  
  // Find the business by ID
  const business = businesses.find(b => b.id === parseInt(id)) || businesses[0];

  const handleContactSeller = () => {
    setShowContactForm(true);
  };

  const closeContactForm = () => {
    setShowContactForm(false);
  };

  return (
    <div className="business-detail-page">
      <section className="business-header py-12 bg-brand-light">
        <div className="container mx-auto px-4">
          <div className="breadcrumb text-gray-600 mb-4">
            <a href="/acquire/listings" className="text-brand-primary hover:underline">Business Listings</a> / {business.name}
          </div>
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center">
            <div>
              <h1 className="text-3xl font-bold mb-2">{business.name}</h1>
              <p className="text-gray-600 mb-4">{business.industry} • {business.location}</p>
              <div className="flex flex-wrap gap-4">
                <div className="bg-white px-4 py-2 rounded-lg">
                  <span className="text-gray-600">Asking Price</span>
                  <div className="text-2xl font-bold text-brand-primary">{business.price}</div>
                </div>
                <div className="bg-white px-4 py-2 rounded-lg">
                  <span className="text-gray-600">Revenue</span>
                  <div className="text-2xl font-bold">{business.revenue}</div>
                </div>
                <div className="bg-white px-4 py-2 rounded-lg">
                  <span className="text-gray-600">EBITDA</span>
                  <div className="text-2xl font-bold">{business.ebitda}</div>
                </div>
              </div>
            </div>
            <div className="mt-6 md:mt-0">
              <button className="btn btn-primary btn-lg" onClick={handleContactSeller}>
                Contact Seller
              </button>
            </div>
          </div>
        </div>
      </section>

      <section className="business-content py-12">
        <div className="container mx-auto px-4">
          <div className="flex flex-wrap border-b">
            <button 
              className={`py-4 px-6 font-semibold ${activeTab === 'overview' ? 'text-brand-primary border-b-2 border-brand-primary' : 'text-gray-600'}`}
              onClick={() => setActiveTab('overview')}
            >
              Overview
            </button>
            <button 
              className={`py-4 px-6 font-semibold ${activeTab === 'financials' ? 'text-brand-primary border-b-2 border-brand-primary' : 'text-gray-600'}`}
              onClick={() => setActiveTab('financials')}
            >
              Financials
            </button>
            <button 
              className={`py-4 px-6 font-semibold ${activeTab === 'due-diligence' ? 'text-brand-primary border-b-2 border-brand-primary' : 'text-gray-600'}`}
              onClick={() => setActiveTab('due-diligence')}
            >
              Due Diligence
            </button>
          </div>

          <div className="py-8">
            {activeTab === 'overview' && (
              <div className="overview-tab">
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                  <div className="lg:col-span-2">
                    <h2 className="text-2xl font-bold mb-4">Business Description</h2>
                    <p className="text-gray-700 mb-6">{business.description}</p>
                    
                    <h3 className="text-xl font-bold mb-4">Business Highlights</h3>
                    <ul className="list-disc pl-6 mb-6">
                      {business.highlights.map((highlight, index) => (
                        <li key={index} className="mb-2 text-gray-700">{highlight}</li>
                      ))}
                    </ul>
                  </div>
                  
                  <div className="business-sidebar">
                    <div className="bg-white rounded-xl shadow-md p-6 mb-6">
                      <h3 className="text-lg font-bold mb-4">Business Details</h3>
                      <div className="space-y-3">
                        <div className="flex justify-between border-b pb-2">
                          <span className="text-gray-600">Industry</span>
                          <span className="font-medium">{business.industry}</span>
                        </div>
                        <div className="flex justify-between border-b pb-2">
                          <span className="text-gray-600">Location</span>
                          <span className="font-medium">{business.location}</span>
                        </div>
                        <div className="flex justify-between border-b pb-2">
                          <span className="text-gray-600">Established</span>
                          <span className="font-medium">{business.established}</span>
                        </div>
                        <div className="flex justify-between border-b pb-2">
                          <span className="text-gray-600">Employees</span>
                          <span className="font-medium">{business.employees}</span>
                        </div>
                        <div className="flex justify-between border-b pb-2">
                          <span className="text-gray-600">Website</span>
                          <a href={business.website} className="font-medium text-brand-primary hover:underline">{business.website}</a>
                        </div>
                      </div>
                    </div>
                    
                    <div className="bg-white rounded-xl shadow-md p-6">
                      <h3 className="text-lg font-bold mb-4">AI Valuation Insights</h3>
                      <div className="valuation-metric mb-4">
                        <div className="flex justify-between mb-1">
                          <span className="text-gray-600">Valuation Confidence</span>
                          <span className="font-medium">High (87%)</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2">
                          <div className="bg-brand-primary h-2 rounded-full" style={{width: '87%'}}></div>
                        </div>
                      </div>
                      <div className="valuation-metric mb-4">
                        <div className="flex justify-between mb-1">
                          <span className="text-gray-600">Growth Potential</span>
                          <span className="font-medium">Strong</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2">
                          <div className="bg-brand-primary h-2 rounded-full" style={{width: '75%'}}></div>
                        </div>
                      </div>
                      <div className="valuation-metric">
                        <div className="flex justify-between mb-1">
                          <span className="text-gray-600">Risk Assessment</span>
                          <span className="font-medium">Low</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2">
                          <div className="bg-brand-primary h-2 rounded-full" style={{width: '25%'}}></div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'financials' && (
              <div className="financials-tab">
                <h2 className="text-2xl font-bold mb-6">Financial Performance</h2>
                <div className="bg-white rounded-xl shadow-md overflow-hidden">
                  <table className="min-w-full">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="py-3 px-6 text-left">Year</th>
                        <th className="py-3 px-6 text-left">Revenue</th>
                        <th className="py-3 px-6 text-left">Profit</th>
                        <th className="py-3 px-6 text-left">Growth Rate</th>
                      </tr>
                    </thead>
                    <tbody>
                      {Object.entries(business.financials).map(([year, data]) => (
                        <tr key={year} className="border-b">
                          <td className="py-4 px-6 font-medium">{year}</td>
                          <td className="py-4 px-6">{data.revenue}</td>
                          <td className="py-4 px-6">{data.profit}</td>
                          <td className="py-4 px-6">
                            <span className="text-green-600 font-medium">{data.growth}</span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                
                <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="bg-white rounded-xl shadow-md p-6">
                    <h3 className="text-xl font-bold mb-4">Revenue Breakdown</h3>
                    <div className="h-64 bg-gray-100 rounded-lg flex items-center justify-center">
                      <p className="text-gray-500">Revenue chart visualization</p>
                    </div>
                  </div>
                  <div className="bg-white rounded-xl shadow-md p-6">
                    <h3 className="text-xl font-bold mb-4">Expense Analysis</h3>
                    <div className="h-64 bg-gray-100 rounded-lg flex items-center justify-center">
                      <p className="text-gray-500">Expense chart visualization</p>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'due-diligence' && (
              <div className="due-diligence-tab">
                <h2 className="text-2xl font-bold mb-6">Due Diligence Documents</h2>
                <p className="text-gray-700 mb-6">
                  All documents have been verified by our team and are available for review by qualified buyers.
                </p>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="document-category bg-white rounded-xl shadow-md p-6">
                    <h3 className="text-xl font-bold mb-4">Financial Documents</h3>
                    <ul className="space-y-3">
                      <li className="flex items-center">
                        <div className="w-8 h-8 rounded-full bg-brand-primary flex items-center justify-center mr-3">
                          <span className="text-white text-sm">✓</span>
                        </div>
                        <span>Audited Financial Statements (3 years)</span>
                      </li>
                      <li className="flex items-center">
                        <div className="w-8 h-8 rounded-full bg-brand-primary flex items-center justify-center mr-3">
                          <span className="text-white text-sm">✓</span>
                        </div>
                        <span>Bank Statements (12 months)</span>
                      </li>
                      <li className="flex items-center">
                        <div className="w-8 h-8 rounded-full bg-brand-primary flex items-center justify-center mr-3">
                          <span className="text-white text-sm">✓</span>
                        </div>
                        <span>Tax Returns (3 years)</span>
                      </li>
                    </ul>
                  </div>
                  
                  <div className="document-category bg-white rounded-xl shadow-md p-6">
                    <h3 className="text-xl font-bold mb-4">Legal Documents</h3>
                    <ul className="space-y-3">
                      <li className="flex items-center">
                        <div className="w-8 h-8 rounded-full bg-brand-primary flex items-center justify-center mr-3">
                          <span className="text-white text-sm">✓</span>
                        </div>
                        <span>Corporate Bylaws</span>
                      </li>
                      <li className="flex items-center">
                        <div className="w-8 h-8 rounded-full bg-brand-primary flex items-center justify-center mr-3">
                          <span className="text-white text-sm">✓</span>
                        </div>
                        <span>Intellectual Property Assignments</span>
                      </li>
                      <li className="flex items-center">
                        <div className="w-8 h-8 rounded-full bg-brand-primary flex items-center justify-center mr-3">
                          <span className="text-white text-sm">✓</span>
                        </div>
                        <span>Lease Agreements</span>
                      </li>
                    </ul>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </section>

      <section className="cta-section py-16 bg-brand-dark">
        <div className="container mx-auto px-4 text-center">
          <h2 className="text-3xl font-bold mb-4">Ready to Make an Offer?</h2>
          <p className="text-xl mb-8 max-w-2xl mx-auto">
            Connect with the seller and take the next step in acquiring this business
          </p>
          <button className="btn btn-primary btn-lg" onClick={handleContactSeller}>
            Contact Seller
          </button>
        </div>
      </section>

      {/* Contact Form Modal */}
      {showContactForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl max-w-md w-full max-h-screen overflow-y-auto">
            <div className="p-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-2xl font-bold">Contact Seller</h3>
                <button 
                  className="text-gray-500 hover:text-gray-700 text-2xl"
                  onClick={closeContactForm}
                >
                  &times;
                </button>
              </div>
              <p className="text-gray-600 mb-6">
                Send a message to the seller of {business.name}. They will receive your inquiry and contact you shortly.
              </p>
              <form>
                <div className="mb-4">
                  <label className="block text-gray-700 mb-2" htmlFor="name">
                    Full Name
                  </label>
                  <input
                    type="text"
                    id="name"
                    className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-primary"
                    placeholder="Enter your full name"
                  />
                </div>
                <div className="mb-4">
                  <label className="block text-gray-700 mb-2" htmlFor="email">
                    Email Address
                  </label>
                  <input
                    type="email"
                    id="email"
                    className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-primary"
                    placeholder="Enter your email address"
                  />
                </div>
                <div className="mb-4">
                  <label className="block text-gray-700 mb-2" htmlFor="message">
                    Message
                  </label>
                  <textarea
                    id="message"
                    rows="4"
                    className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-primary"
                    placeholder="Tell the seller about your interest in their business..."
                  ></textarea>
                </div>
                <div className="flex justify-end space-x-3">
                  <button 
                    type="button"
                    className="btn btn-secondary"
                    onClick={closeContactForm}
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit"
                    className="btn btn-primary"
                  >
                    Send Message
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default BusinessDetailPage;