import React, { useEffect, useState, useRef } from 'react';
import { createHashRouter, RouterProvider } from 'react-router-dom';
import { ThemeProvider } from './components/WorkflowAI/contexts/ThemeContext';
import PremiumLandingPage from './components/PremiuimStuff/layout/PremiumLandingPage.jsx';
import WorkflowAI from './components/WorkflowAI/WorkflowAI';
import PitchDeck from './components/PitchDeck/PitchDeck.jsx';
import AcquireLandingPage from './components/Acquire/AcquireLandingPage.jsx';
import BusinessListingsPage from './components/Acquire/BusinessListingsPage.jsx';
import BusinessDetailPage from './components/Acquire/BusinessDetailPage.jsx';
import InvestorProfile from './components/Acquire/InvestorProfile.js';
import InvestorsDirectory from './components/Acquire/InvestorsDirectory.jsx';
import SellBusinessPage from './components/Acquire/SellBusinessPage.jsx';
import AcquireApp from './components/Acquire/AcquireApp.jsx';
import './App.css';

// Create hash router for better GitHub Pages compatibility
const router = createHashRouter([
  {
    path: "/",
    element: <PremiumLandingPage />,
  },
  {
    path: "/workflow-ai",
    element: <WorkflowAI />,
  },
  {
    path: "/pitch-deck",
    element: <PitchDeck />,
  },
  {
    path: "/acquire",
    element: <AcquireApp />,
    children: [
      {
        index: true,
        element: <AcquireLandingPage />,
      },
      {
        path: "listings",
        element: <BusinessListingsPage />,
      },
      {
        path: "business/:id",
        element: <BusinessDetailPage />,
      },
      {
        path: "investor/:id",
        element: <InvestorProfile />,
      },
      {
        path: "investors",
        element: <InvestorsDirectory />,
      },
      {
        path: "sell",
        element: <SellBusinessPage />,
      },
    ],
  },
]);

function App() {
  const [originalTitle] = useState('Busin.US'); // Store the original title
  const intervalRef = useRef(null); // Ref to store the interval ID

  useEffect(() => {
    // Function to handle visibility change
    const handleVisibilityChange = () => {
      if (document.hidden) {
        // User left the tab - start the looping sequence
        let step = 0;
        
        // Clear any existing interval
        if (intervalRef.current) {
          clearInterval(intervalRef.current);
        }
        
        // Set the first part of the message immediately
        document.title = "You just lost";
        
        // Start the looping interval
        intervalRef.current = setInterval(() => {
          if (step % 2 === 0) {
            // Show "The game"
            document.title = "The game";
          } else {
            // Show "you just lost"
            document.title = "you just lost";
          }
          step++;
        }, 1000); // Change every second
      } else {
        // User returned to the tab
        // Clear the interval
        if (intervalRef.current) {
          clearInterval(intervalRef.current);
          intervalRef.current = null;
        }
        // Reset to original title
        document.title = originalTitle;
      }
    };

    // Add event listener for visibility change
    document.addEventListener('visibilitychange', handleVisibilityChange);

    // Cleanup function to remove event listener and clear interval
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      // Clear interval if it's running
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
      // Reset title when component unmounts
      document.title = originalTitle;
    };
  }, [originalTitle]);

  return (
    <div className="App">
      <ThemeProvider>
        <RouterProvider router={router} />
      </ThemeProvider>
    </div>
  );
}

export default App;