import React, { useState } from 'react';
import { useOutletContext } from 'react-router-dom';
import './acquire.css';

const InvestorsDirectory = () => {
  const [filter, setFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  
  // Get data from the Outlet context
  const { investors } = useOutletContext();

  const filteredInvestors = investors.filter(investor => {
    const matchesFilter = filter === 'all' || investor.focus.toLowerCase().includes(filter.toLowerCase());
    const matchesSearch = investor.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          investor.title.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  return (
    <div className="investors-directory-page">
      <section className="directory-header py-16 bg-brand-light">
        <div className="container mx-auto px-4 text-center">
          <h1 className="text-4xl font-bold mb-4">Investor Directory</h1>
          <p className="text-xl max-w-2xl mx-auto mb-8">
            Connect with qualified investors actively seeking acquisition opportunities
          </p>
          
          <div className="search-filters max-w-3xl mx-auto">
            <div className="search-bar mb-6">
              <input
                type="text"
                placeholder="Search investors by name or focus area..."
                className="w-full p-4 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-brand-primary"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            
            <div className="filters flex flex-wrap justify-center gap-4">
              <button 
                className={`filter-btn ${filter === 'all' ? 'btn btn-primary' : 'btn btn-secondary'}`}
                onClick={() => setFilter('all')}
              >
                All Investors
              </button>
              <button 
                className={`filter-btn ${filter === 'Technology' ? 'btn btn-primary' : 'btn btn-secondary'}`}
                onClick={() => setFilter('Technology')}
              >
                Technology
              </button>
              <button 
                className={`filter-btn ${filter === 'Healthcare' ? 'btn btn-primary' : 'btn btn-secondary'}`}
                onClick={() => setFilter('Healthcare')}
              >
                Healthcare
              </button>
              <button 
                className={`filter-btn ${filter === 'Real Estate' ? 'btn btn-primary' : 'btn btn-secondary'}`}
                onClick={() => setFilter('Real Estate')}
              >
                Real Estate
              </button>
            </div>
          </div>
        </div>
      </section>

      <section className="directory py-16">
        <div className="container mx-auto px-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredInvestors.map(investor => (
              <div key={investor.id} className="investor-card bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-xl transition-shadow">
                <div className="investor-header bg-brand-primary p-6 text-white">
                  <div className="investor-avatar w-16 h-16 bg-white rounded-full mb-4 mx-auto flex items-center justify-center">
                    <span className="text-brand-primary text-2xl font-bold">{investor.name.charAt(0)}</span>
                  </div>
                  <h3 className="text-xl font-bold text-center">{investor.name}</h3>
                  <p className="text-center text-brand-light">{investor.title}</p>
                </div>
                <div className="investor-details p-6">
                  <div className="investor-meta mb-4">
                    <div className="flex justify-between text-sm mb-2">
                      <span className="text-gray-600">Focus:</span>
                      <span className="font-medium">{investor.focus}</span>
                    </div>
                    <div className="flex justify-between text-sm mb-2">
                      <span className="text-gray-600">Min Investment:</span>
                      <span className="font-medium">{investor.minInvestment}</span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-600">Geography:</span>
                      <span className="font-medium">{investor.location}</span>
                    </div>
                  </div>
                  <button className="btn btn-primary w-full">View Profile</button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="cta-section py-16 bg-brand-dark">
        <div className="container mx-auto px-4 text-center">
          <h2 className="text-3xl font-bold mb-4">List Your Business</h2>
          <p className="text-xl mb-8 max-w-2xl mx-auto">
            Reach qualified investors and get the best value for your business
          </p>
          <button className="btn btn-primary btn-lg">List Your Business</button>
        </div>
      </section>
    </div>
  );
};

export default InvestorsDirectory;