import React, { useState, useEffect } from 'react';
import { Outlet } from 'react-router-dom';
import Layout from './Layout';
import useAcquire from './useAcquire';

const AcquireApp = () => {
  const { businesses, investors, loading, error } = useAcquire();
  const [user, setUser] = useState(null);
  const [favorites, setFavorites] = useState([]);
  const [notifications, setNotifications] = useState([]);

  // Initialize from localStorage
  useEffect(() => {
    const savedUser = localStorage.getItem('acquire_user');
    const savedFavorites = localStorage.getItem('acquire_favorites');
    const savedNotifications = localStorage.getItem('acquire_notifications');
    
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    
    if (savedFavorites) {
      setFavorites(JSON.parse(savedFavorites));
    }
    
    if (savedNotifications) {
      setNotifications(JSON.parse(savedNotifications));
    }
  }, []);

  // Save to localStorage when state changes
  useEffect(() => {
    if (user) {
      localStorage.setItem('acquire_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('acquire_user');
    }
  }, [user]);

  useEffect(() => {
    localStorage.setItem('acquire_favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    localStorage.setItem('acquire_notifications', JSON.stringify(notifications));
  }, [notifications]);

  const handleLogin = () => {
    // Simulate login
    const newUser = {
      id: 1,
      name: 'John Doe',
      email: 'john@example.com',
      role: 'buyer'
    };
    setUser(newUser);
    
    // Add welcome notification
    const welcomeNotification = {
      id: Date.now(),
      title: 'Welcome to Acquire.Busin.US',
      message: 'Your account has been created successfully. Start exploring business opportunities!',
      timestamp: new Date().toISOString(),
      read: false
    };
    setNotifications(prev => [welcomeNotification, ...prev]);
  };

  const handleLogout = () => {
    setUser(null);
    setFavorites([]);
    setNotifications([]);
    localStorage.removeItem('acquire_user');
    localStorage.removeItem('acquire_favorites');
    localStorage.removeItem('acquire_notifications');
  };

  const handleFavorite = (businessId) => {
    setFavorites(prev => {
      if (prev.includes(businessId)) {
        return prev.filter(id => id !== businessId);
      } else {
        return [...prev, businessId];
      }
    });
  };

  const handleNotificationClick = () => {
    // In a real app, this would open a notification panel
    console.log('Notifications clicked');
  };

  const handleMarkAsRead = (notificationId) => {
    setNotifications(prev => 
      prev.map(notification => 
        notification.id === notificationId 
          ? { ...notification, read: true } 
          : notification
      )
    );
  };

  const handleMarkAllAsRead = () => {
    setNotifications(prev => 
      prev.map(notification => ({ ...notification, read: true }))
    );
  };

  const handleClearAll = () => {
    setNotifications([]);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-brand-primary mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading Acquire.Busin.US...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-red-100">
            <svg className="h-6 w-6 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
          <h3 className="mt-2 text-lg font-medium text-gray-900">Error loading data</h3>
          <p className="mt-1 text-gray-500">{error}</p>
          <button
            onClick={() => window.location.reload()}
            className="mt-4 inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-brand-primary hover:bg-brand-primary-dark focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-primary"
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <Layout
      user={user}
      onLogin={handleLogin}
      onLogout={handleLogout}
      onNotificationClick={handleNotificationClick}
      notificationCount={notifications.filter(n => !n.read).length}
    >
      <Outlet context={{ 
        businesses, 
        investors, 
        favorites, 
        onFavorite: handleFavorite,
        notifications,
        onMarkAsRead: handleMarkAsRead,
        onMarkAllAsRead: handleMarkAllAsRead,
        onClearAll: handleClearAll
      }} />
    </Layout>
  );
};

export default AcquireApp;