import React, { useState } from 'react';
import { sendWorkflowToTelegram } from './TelegramService';

const WorkflowSignupModal = ({ isOpen, onClose, onExport, nodes, edges, groups, onShowAlert, businessPlanText, onGenerate }) => {
  const [signupName, setSignupName] = useState('');
  const [signupEmail, setSignupEmail] = useState('');
  const [isSignupSubmitted, setIsSignupSubmitted] = useState(false);

  const isValidEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  const handleSignupSubmit = (e) => {
    e.preventDefault();
    
    if (!signupName.trim()) {
      onShowAlert && onShowAlert('Validation Error', "Please enter your name.");
      return;
    }
    
    if (!isValidEmail(signupEmail)) {
      onShowAlert && onShowAlert('Validation Error', "Please enter a valid email address.");
      return;
    }
    
    // Save to localStorage
    const signupData = {
      name: signupName,
      email: signupEmail,
      timestamp: new Date().toISOString()
    };
    localStorage.setItem('busin.us-signup', JSON.stringify(signupData));
    
    // Send to Telegram with workflow data
    sendWorkflowToTelegram(signupName, signupEmail, nodes, edges, groups);
    
    // Close the modal and proceed with export
    onClose();
    onExport();
  };

  const handleSignupSuccess = () => {
    // Close modal and trigger business plan generation
    onClose();
    onGenerate(businessPlanText);
  };

  if (!isOpen) return null;

  return (
    <>
      <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
        <div 
          className="bg-dark-surface rounded-xl border border-dark-border shadow-2xl w-full max-w-md animate-in fade-in zoom-in-95"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="p-6">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold text-dark-text-primary">
                {isSignupSubmitted ? 'Thank You!' : 'Join Our Waitlist'}
              </h2>
              <button
                onClick={onClose}
                className="text-dark-text-secondary hover:text-dark-text-primary transition-colors"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            
            {isSignupSubmitted ? (
              <div className="text-center py-8">
                <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center mx-auto mb-4">
                  <svg className="w-8 h-8 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                  </svg>
                </div>
                <h3 className="text-lg font-semibold text-dark-text-primary mb-2">
                  You're on the list!
                </h3>
                <p className="text-dark-text-secondary">
                  Thank you for joining our waitlist. We'll notify you when premium features become available.
                </p>
                <button
                  onClick={onClose}
                  className="px-4 py-2 bg-dark-bg text-white rounded-lg hover:bg-dark-surface transition-colors mt-6"
                >
                  Close
                </button>
              </div>
            ) : (
              <>
                <p className="text-dark-text-secondary mb-6">
                  Sign up for our newsletter to unlock full export capabilities and receive business planning insights.
                </p>
                
                <form onSubmit={handleSignupSubmit} className="space-y-4">
                  <div>
                    <label className="block text-dark-text-secondary text-sm font-medium mb-2">
                      Full Name
                    </label>
                    <input
                      type="text"
                      value={signupName}
                      onChange={(e) => setSignupName(e.target.value)}
                      className="w-full px-4 py-3 bg-dark-bg border border-dark-border rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-primary text-dark-text-primary"
                      placeholder="Your full name"
                      required
                    />
                  </div>
                  
                  <div>
                    <label className="block text-dark-text-secondary text-sm font-medium mb-2">
                      Email Address
                    </label>
                    <input
                      type="email"
                      value={signupEmail}
                      onChange={(e) => setSignupEmail(e.target.value)}
                      className="w-full px-4 py-3 bg-dark-bg border border-dark-border rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-primary text-dark-text-primary"
                      placeholder="your@email.com"
                      required
                    />
                  </div>
                  
                  <button
                    type="submit"
                    className="w-full px-4 py-3 bg-brand-primary text-white font-semibold rounded-lg hover:bg-brand-primary/90 transition-colors"
                  >
                    Join Waitlist
                  </button>
                </form>
                
                <div className="mt-4 text-xs text-dark-text-secondary">
                  By signing up, you agree to our Privacy Policy and Terms of Service.
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

export default WorkflowSignupModal;